/**
 * `buildSimplePdfFromText`, the fallback that renders a text-only source's
 * `pageHtml` into a new, minimal PDF for download — see its own doc
 * comment. Verified the same way `ocrOverlay.test.ts` verifies pdf-lib
 * output: re-parse the generated bytes with pdfjs-dist's Node-friendly
 * "legacy" build and check what actually comes back out.
 */
import { describe, expect, it } from 'vitest'
import * as pdfjsLegacy from 'pdfjs-dist/legacy/build/pdf.mjs'
import { buildSimplePdfFromText } from '../pdfFromText'

function toArrayBuffer(bytes: Uint8Array): ArrayBuffer {
  return bytes.slice().buffer
}

async function loadDoc(bytes: Uint8Array) {
  return pdfjsLegacy.getDocument({ data: toArrayBuffer(bytes) }).promise
}

async function pageText(doc: Awaited<ReturnType<typeof loadDoc>>, pageNum: number): Promise<string> {
  const page = await doc.getPage(pageNum)
  const content = await page.getTextContent()
  return content.items.map((it: any) => ('str' in it ? it.str : '')).join(' ')
}

describe('buildSimplePdfFromText', () => {
  it('includes the title, subtitle, and body text on a single page when it all fits', async () => {
    const bytes = await buildSimplePdfFromText({
      title: 'A Short Paper',
      subtitle: 'Jane Tester (2024). A Short Paper. Journal of Examples.',
      pageHtml: ['<p>This is the extracted body text of the source.</p>'],
    })
    const doc = await loadDoc(bytes)
    expect(doc.numPages).toBe(1)
    const text = await pageText(doc, 1)
    expect(text).toContain('A Short Paper')
    expect(text).toContain('Jane Tester')
    expect(text).toContain('This is the extracted body text of the source.')
  })

  it('inserts a page marker between each original page worth of text, only when there is more than one page', async () => {
    const onePage = await buildSimplePdfFromText({ title: 'T', pageHtml: ['<p>Only page.</p>'] })
    const onePageText = await pageText(await loadDoc(onePage), 1)
    expect(onePageText).not.toMatch(/page 1/)

    const twoPages = await buildSimplePdfFromText({ title: 'T', pageHtml: ['<p>First page text.</p>', '<p>Second page text.</p>'] })
    const twoPageDoc = await loadDoc(twoPages)
    const fullText = await pageText(twoPageDoc, 1)
    expect(fullText).toMatch(/page 1/)
    expect(fullText).toMatch(/page 2/)
    expect(fullText).toContain('First page text.')
    expect(fullText).toContain('Second page text.')
  })

  it('flows long text across multiple output PDF pages', async () => {
    const wordCount = 3000
    const longParagraph = Array.from({ length: wordCount }, (_, i) => `word${i}`).join(' ')
    const bytes = await buildSimplePdfFromText({ title: 'Long Document', pageHtml: [`<p>${longParagraph}</p>`] })
    const doc = await loadDoc(bytes)
    expect(doc.numPages).toBeGreaterThan(1)
    const page1Text = await pageText(doc, 1)
    const lastPageText = await pageText(doc, doc.numPages)
    expect(page1Text).toContain('word0')
    expect(page1Text).not.toContain(`word${wordCount - 1}`)
    expect(lastPageText).toContain(`word${wordCount - 1}`)
  })

  it('substitutes common "smart" typography rather than dropping it', async () => {
    const bytes = await buildSimplePdfFromText({ title: 'T', pageHtml: ['<p>A “quoted” phrase — with an ellipsis…</p>'] })
    const text = await pageText(await loadDoc(bytes), 1)
    expect(text).toContain('"quoted"')
    expect(text).toContain('--')
    expect(text).toContain('...')
  })

  it('falls back to a literal ? for characters outside the standard font, without throwing', async () => {
    const bytes = await buildSimplePdfFromText({ title: 'T', pageHtml: ['<p>Unsupported: 日本語 text follows.</p>'] })
    const text = await pageText(await loadDoc(bytes), 1)
    expect(text).toContain('???')
    expect(text).toContain('text follows.')
  })

  it('notes when a source has no extracted text at all, rather than producing a blank body', async () => {
    const bytes = await buildSimplePdfFromText({ title: 'Empty Source', pageHtml: ['', '<p></p>'] })
    const text = await pageText(await loadDoc(bytes), 1)
    expect(text).toContain('Empty Source')
    expect(text).toMatch(/no extracted text/i)
  })

  it('falls back to a title when none is given', async () => {
    const bytes = await buildSimplePdfFromText({ title: '', pageHtml: ['<p>Body.</p>'] })
    const text = await pageText(await loadDoc(bytes), 1)
    expect(text).toContain('Untitled source')
  })
})
